const body = $input.first().json.body || $input.first().json;
const figmaUrl = body.figma_url || '';
const match = figmaUrl.match(/figma\.com\/(?:file|design)\/([a-zA-Z0-9]+)/);
if (!match) throw new Error('Invalid Figma URL');
return [{ json: { file_key: match[1], requirements: body.requirements, figma_url: figmaUrl } }];

const figmaData = $input.first().json;
const requirements = $('Parse Figma URL').first().json.requirements;
const figmaUrl = $('Parse Figma URL').first().json.figma_url;

const document = figmaData.document || {};
const fileName = figmaData.name || 'Unknown';

const screens = [];
const components = [];
const textStyles = [];
const colors = [];

function traverse(node, depth = 0) {
  const type = node.type || '';
  const name = node.name || '';
  if (['FRAME','COMPONENT','INSTANCE'].includes(type) && depth <= 3) {
    if (depth <= 1) screens.push(name);
    else components.push(name);
  }
  if (type === 'TEXT') {
    const style = node.style || {};
    const entry = `${style.fontFamily || ''}/${style.fontSize || ''}px`;
    if (style.fontFamily && !textStyles.includes(entry)) textStyles.push(entry);
  }
  (node.fills || []).forEach(fill => {
    if (fill.type === 'SOLID') {
      const c = fill.color || {};
      const hex = `#${Math.round(c.r*255).toString(16).padStart(2,'0')}${Math.round(c.g*255).toString(16).padStart(2,'0')}${Math.round(c.b*255).toString(16).padStart(2,'0')}`;
      if (!colors.includes(hex)) colors.push(hex);
    }
  });
  (node.children || []).forEach(child => traverse(child, depth + 1));
}
traverse(document);

const uniqueScreens = [...new Set(screens)].slice(0, 30);
const uniqueComponents = [...new Set(components)].slice(0, 60);

return [{ json: {
  requirements,
  figma_url: figmaUrl,
  design_summary: {
    file_name: fileName,
    screens: uniqueScreens,
    components: uniqueComponents,
    text_styles: [...new Set(textStyles)].slice(0, 20),
    colors: [...new Set(colors)].slice(0, 30)
  }
} }];

const data = $input.first().json;
const ds = data.design_summary;

const systemPrompt = `You are an expert UI/UX Requirement Validation Analyst and QA Engineer.
Your job is to compare software requirements against a Figma design summary and identify ALL mismatches.
You MUST respond with a single valid JSON object and nothing else.
JSON schema:
{
  "overall_score": <int 0-100>,
  "requirement_coverage": <float 0-100>,
  "ai_summary": "<string>",
  "issues": [
    {
      "category": "<Requirement Coverage|Missing Screen|Missing Component|Missing Button|Missing Form|Missing Input|Missing Navigation|Missing Validation|Missing State|Typography|Color|Spacing|Responsive|Accessibility|UI Consistency|UX Problem|Business Logic|Design Quality>",
      "severity": "<critical|high|medium|low>",
      "title": "<string>",
      "description": "<string>",
      "location": "<screen or null>",
      "recommendation": "<string>"
    }
  ]
}`;

const userPrompt = `Analyze:

=== SOFTWARE REQUIREMENTS ===
${data.requirements}

=== FIGMA DESIGN SUMMARY ===
File: ${ds.file_name}
Screens: ${ds.screens.join(', ') || 'None'}
Components: ${ds.components.join(', ') || 'None'}
Text styles: ${ds.text_styles.join(', ') || 'None'}
Colors: ${ds.colors.join(', ') || 'None'}

Identify every mismatch. Return ONLY the JSON object.`;

return [{ json: { system_prompt: systemPrompt, user_prompt: userPrompt, design_summary: ds } }];

const grokResp = $input.first().json;
const designSummary = $('Build AI Prompt').first().json.design_summary;

let rawContent = grokResp.choices[0].message.content.trim();
if (rawContent.startsWith('```')) {
  rawContent = rawContent.split('```')[1];
  if (rawContent.startsWith('json')) rawContent = rawContent.slice(4);
}
rawContent = rawContent.trim();

let parsed;
try {
  parsed = JSON.parse(rawContent);
} catch(e) {
  throw new Error('Grok returned invalid JSON: ' + e.message);
}

const issues = (parsed.issues || []).map((issue, i) => ({
  id: `issue-${String(i+1).padStart(3,'0')}`,
  category: issue.category || 'General',
  severity: ['critical','high','medium','low'].includes(issue.severity) ? issue.severity : 'medium',
  title: issue.title || 'Unnamed issue',
  description: issue.description || '',
  location: issue.location || null,
  recommendation: issue.recommendation || ''
}));

const counts = { critical: 0, high: 0, medium: 0, low: 0 };
issues.forEach(i => counts[i.severity] = (counts[i.severity] || 0) + 1);

const report = {
  overall_score: Math.max(0, Math.min(100, parseInt(parsed.overall_score) || 50)),
  requirement_coverage: Math.max(0, Math.min(100, parseFloat(parsed.requirement_coverage) || 50)),
  total_issues: issues.length,
  critical_count: counts.critical,
  high_count: counts.high,
  medium_count: counts.medium,
  low_count: counts.low,
  issues,
  ai_summary: parsed.ai_summary || 'Analysis complete.',
  figma_file_name: designSummary.file_name,
  screens_found: designSummary.screens,
  components_found: designSummary.components
};

return [{ json: report }];
